// `checkdata.txt`: what the seed's locations are, generated by
// `tools/gen_checkdata.py` from the same `campaign.json` the apworld reads.
//
// Read once per map load. The format is line-oriented and pipe-delimited; see
// the header of the generated file for the record types.
//
// A charger's identity is where it stands, never its brush model index: Valve
// recompiles single-player maps from time to time and a recompile renumbers
// brush models, which would silently repoint every charger id in that map.
//
// Matching is by nearest unit rather than by equal coordinates. The generator
// snaps its key to a coarse grid so ids stay stable across regenerations, but
// this side does not have to reproduce that rounding: the closest charger of the
// same classname in the same map wins, and two of them are never near each other
// -- the tightest pair in the whole campaign is 204 units apart, and the tightest
// pair of *any* two chargers is 48. See `kChargerMatchRadius`.

#pragma once

#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

namespace ap {

enum class TriggerType {
    Unknown,
    MapReached,
    ChapterComplete,
    Charger,
    WeaponPickup,
    Fired,
    HealPickup,  // format 7: Healsanity
    AmmoPickup,  // format 7: Ammosanity
    Scientist,   // format 8: Scientistsanity
    Barney,      // format 8: Barneysanity
    Soldier,     // format 8: Soldiersanity
};

struct Location {
    long id = 0;
    std::string map;
    TriggerType type = TriggerType::Unknown;
    std::string name;

    // chapter_complete: the chapter key. weapon_pickup: the classnames, any one
    // of which fires it.
    std::string chapter;
    std::vector<std::string> classnames;

    // charger: the classname of the unit and where it stands.
    std::string charger_classname;
    float at[3] = {0, 0, 0};

    // fired: the targetname whose firing sends it.
    std::string fires;

    // heal_pickup / ammo_pickup, and scientist / barney, which are keyed like a
    // placed pickup: the entity's classname and `at`, with
    // `ordinal` telling apart two of one classname on the same unit. A placed
    // pickup's `at` is its spawn origin to the unit; a crate's (a
    // `func_breakable` or `func_pushable` that drops one) its rounded centre.
    std::string pickup_classname;
    int ordinal = 1;
    bool crate = false;

    // Where in the world this check is, for ap_find. Not every kind has one:
    // reaching a map is not somewhere a player can be pointed.
    bool has_position = false;
    float position[3] = {0, 0, 0};

    // What reaching it always takes, as item names to print. Empty for most.
    std::string needs;

    // A weapon check's ways in: each mission's first copy, from `F` records.
    // Empty for everything else and in an older data file.
    struct Source {
        std::string map;
        bool has_position = false;
        float position[3] = {0, 0, 0};
        std::string needs;
        std::string drop;  // "hostile" or "ally" for a copy a monster drops
    };
    std::vector<Source> sources;

    // scientist / barney, from `A`, `H` and `R` records: stand-ins the map
    // swaps in for this NPC, keyed like it and tagged as the same check; what
    // `ap_find` says about the check; and whether the map deleting the NPC is
    // its death.
    struct Alias {
        std::string classname;
        float at[3] = {0, 0, 0};
        int ordinal = 1;
    };
    std::vector<Alias> aliases;
    std::string note;
    bool removal_death = false;
    // From an `X` record: hurting it fails the mission, so the hurt sends.
    bool harm_sends = false;
};

struct Chapter {
    int index = 0;
    std::string key;
    std::string name;
    std::vector<std::string> maps;
    bool is_goal = false;

    // How this mission is finished.
    //
    // Normally false: the mission ends when the player walks on into the next
    // one, and that transition is intercepted. Arriving on the last map in the
    // list is *not* the same thing -- `c1a1d` is last in Unforeseen Consequences
    // only because it is furthest from the start, and it is a dead-end side room
    // the player walks back out of.
    //
    // True only for the mission nothing changelevels out of, the finale, where
    // arriving on the last map is the only signal there is and the right one.
    bool complete_on_arrival = false;

    // Format 5. Which game the mission belongs to, and how it completes:
    // "arrival", "forward_exit" or "endsection". An older file names neither,
    // which is Half-Life and the arrival flag above.
    std::string campaign = "half_life";
    std::string complete_on;

    bool CompletesOnEndSection() const { return complete_on == "endsection"; }

    bool HasMap(const std::string& map) const;
    bool IsLastMap(const std::string& map) const;
};

// A monster a map only ever has because the map before it walked one in.
//
// Valve builds a boss fight that spans several maps by placing the monster once
// and letting the engine carry it across each transition. The later maps hold
// the script and the path and no monster at all, which is invisible when the
// chapter is played through and an empty room when it is warped into. This is
// what a warp puts back.
struct CarriedMonster {
    std::string map;
    std::string classname;
    std::string targetname;
    // The path node it starts on, which is the whole of the mid-mission state:
    // remaining health, the animation played on arrival and everything after are
    // read from the chain onward from there.
    std::string netname;
    float origin[3] = {0.0f, 0.0f, 0.0f};
    float angle = 0.0f;
    int spawnflags = 0;
};

// A way off a mission map: a `trigger_changelevel` into another campaign map,
// or a `trigger_endsection` (`to` empty). Where `!trace` points for a part's
// Reached or a mission's Complete.
struct Changelevel {
    std::string map;
    std::string to;
    float at[3] = {0.0f, 0.0f, 0.0f};
};

// One game the seed may include (format 5's `N` record).
struct Campaign {
    std::string key;
    std::string shortname;  // what a player types: `ap_warp of 3`
    std::string name;
    std::string goal_chapter;
    // The item that lets the player hold armour on this game's maps.
    std::string armour_item;
};

class CheckData {
public:
    int format_version = 0;
    std::string data_version;  // must match the client's, or ids differ
    std::string goal_chapter;

    std::vector<Chapter> chapters;
    std::vector<Location> locations;

    // classname -> the item name that must arrive before it may be picked up.
    std::vector<std::pair<std::string, std::string>> gated_classnames;
    // Granted from the first spawn and never taken away. A snapshot's `starting`
    // list overrides this; these are the default rather than the truth.
    std::vector<std::string> starting_weapons;

    // Lobby panel targetname -> the mission it travels to. Empty when the mod
    // folder has no authored lobby in it, which is not an error: the console
    // commands are the whole of the hub without one.
    std::vector<std::pair<std::string, std::string>> hub_buttons;

    // Placed on arrival, but only on a map that was warped into. Reaching one
    // the ordinary way brings the real monster with it, and a second would be
    // two bosses in one arena.
    std::vector<CarriedMonster> carried_monsters;

    // Empty in a file older than the `T` record: no trace to a way on.
    std::vector<Changelevel> changelevels;

    // Every game in the file, in mission order. Empty in a file older than
    // format 5, which is Half-Life alone; see `CampaignByKey`.
    std::vector<Campaign> campaigns;

    // Null for a key the file does not describe. Half-Life is always known,
    // with or without an `N` record, so an older file still has armour.
    const Campaign* CampaignByKey(const std::string& key) const;
    // By its key, short form (`of`) or name, ignoring case and punctuation.
    const Campaign* CampaignByName(const std::string& text) const;
    // The game whose maps these are, or Half-Life for a map in no mission
    // (the hub).
    const Campaign& CampaignOfMap(const std::string& map) const;

    // `extra`, when given and present, is read after `path` as more of it:
    // the scenario harness's test-only records.
    bool Load(const std::string& path, const std::string& extra = "");

    // `map|classname|x y z|ordinal` -> a placed pickup, built by `Load`.
    std::unordered_map<std::string, const Location*> pickup_index;
    bool Loaded() const { return !locations.empty(); }

    // Which mission this lobby panel enters, or null for any other entity the
    // player pressed use on. Matched on the targetname, which is the only handle
    // the map and this file share.
    const Chapter* ChapterOfButton(const std::string& targetname) const;

    // Which mission a map belongs to, or null for a map not in the campaign --
    // a deathmatch map, the hub, or the hazard course.
    const Chapter* ChapterOfMap(const std::string& map) const;
    const Chapter* ChapterByKey(const std::string& key) const;
    // By index as `ap_warp 7` takes it, or by name.
    //
    // Name matching ignores case and punctuation entirely, and will take a
    // chapter key or any of its map names: `Gonarch's Lair`, `gonarchs lair`,
    // `gonarch` and `c4a2` are all the same request. A player typing a mission
    // name is not transcribing it.
    const Chapter* ChapterByIndex(int index) const;
    const Chapter* ChapterByName(const std::string& text) const;

    const Location* LocationById(long id) const;

    // The pickup placed with this classname at this spawn origin, rounded to
    // the unit, and the `ordinal`th of them there in spawn order. Exact: two
    // pickups a few units apart are two checks, so nothing near is close enough.
    const Location* PickupAt(const std::string& map, const std::string& classname,
                             const int at[3], int ordinal) const;
    // The crate of this classname nearest `centre` in this map, within
    // kCrateMatchRadius.
    const Location* CrateAt(const std::string& map, const std::string& classname,
                            const float centre[3]) const;

    // The charger of this classname nearest `at` in this map, within
    // kChargerMatchRadius. Null when the player pressed use on something else.
    const Location* ChargerAt(const std::string& map, const std::string& classname,
                              const float at[3]) const;

    // The checks this map sends when it fires `targetname`: one event can be
    // several deaths. Empty for nearly every firing there is, so it is cheap
    // to ask about all of them.
    std::vector<const Location*> FiredBy(const std::string& map,
                                         const char* targetname) const;

    // The weapon check this classname fires *in this map*, if any.
    //
    // Both halves matter. There is one check per weapon for the whole run, and
    // it sits where Half-Life would first have handed that weapon over -- the
    // earliest map in campaign order holding one. Finding the same weapon later
    // is not that moment, and finding one in the hub is not it either.
    //
    // It is also what keeps the game honest with generation: the apworld places
    // this location in that map's region, so a check that could fire anywhere
    // would be a check landing somewhere logic never put it.
    const Location* WeaponPickupFor(const std::string& classname,
                                    const std::string& map) const;

    // "" when the classname is not gated at all.
    std::string ItemGating(const std::string& classname) const;
    // Every classname the named item unlocks, for handing it over.
    std::vector<std::string> ClassnamesFor(const std::string& item_name) const;
};

// How far from a charger's recorded position the live entity may be and still be
// the same unit. Chargers are never within 48 units of each other, so this is
// generous enough to absorb any recompile or rounding drift and far too tight to
// confuse two of them.
constexpr float kChargerMatchRadius = 32.0f;

// The same for crates. The generator refuses two crates of one classname closer
// than twice this, and a crate's own grid rounding is at most 3.5 units off.
constexpr float kCrateMatchRadius = 8.0f;

// The key `pickup_index` is built on.
std::string PickupKey(const std::string& map, const std::string& classname,
                      const int at[3], int ordinal);

}  // namespace ap
